from pathlib import Path
import re
root=Path('skyfrontiers3d') if Path('skyfrontiers3d').exists() else Path('.')
html_p=root/'index.html';css_p=root/'style.css';js_p=root/'game.js'
js=js_p.read_text()

# V7 dropped the stylesheet link. Fix that first, then reshape the existing simulator DOM toward the supplied reference.
html=html_p.read_text()
if 'rel="stylesheet"' not in html:
    html=html.replace('<title>Sky Frontiers 3D</title>','<title>Sky Frontiers 3D</title>\n  <link rel="stylesheet" href="./style.css" />')

# Replace V7 flight HUD markup while retaining every ID game.js expects.
start=html.index('  <div id="hud"')
end=html.index('  <div id="menu"',start)
flight=r'''  <div id="startDeck" class="start-deck">
    <div class="top-status"><div class="level-chip"><span>▰</span><b>УРОВЕНЬ 1</b><small>НОВИЧОК</small></div><div class="status-item"><span>★</span><b>0</b></div><div class="status-item money"><span>●</span><b id="startCredits">0</b></div><button class="status-plus" type="button">+</button></div>
    <div class="start-prompt">ДАВАЙТЕ<br><b>ПОЛЕТАЕМ</b><i></i></div>
    <div class="start-nav"><button id="startHangar" type="button"><span class="nav-icon">◆</span><b>Самолёты</b></button><button id="startMissions" type="button"><span class="nav-icon">✦</span><b>Миссии</b></button><button id="startSettings" type="button"><span class="nav-icon">⚙</span><b>Настройки</b></button><button id="takeoffBtn" class="takeoff" type="button"><b>Взлёт</b><span class="plane-glyph">➤</span></button></div>
  </div>

  <div id="hud" class="hud hidden">
    <div class="mission-callout"><span class="radio-dot">◉</span><div><b id="objective">Свободный полёт</b><small id="missionProgress">Исследуйте карту или войдите в маяк задания</small></div></div>
    <div class="left-stack"><div class="altimeter-rail instrument-rail"><i></i><span id="altitude">0</span><small>ALT M</small></div><div class="round-instruments"><div class="round-gauge speed-gauge"><b id="speed">0</b><small>СКОРОСТЬ</small></div><div class="round-gauge radar-gauge"><canvas id="minimap" width="220" height="220"></canvas><small>РАДАР</small></div></div></div>
    <div class="right-stack"><button id="pauseBtn" class="square-action" type="button">Ⅱ</button><button id="timeBtn" class="square-action time" type="button">x1</button></div>
    <div class="throttle-unit"><div class="throttle-slot"><i id="throttleHandle"></i></div><div class="throttle-readout"><span id="throttle">0</span><small>%</small></div><button data-touch="throttleUp" class="throttle-hit up" aria-label="Газ больше">+</button><button data-touch="throttleDown" class="throttle-hit down" aria-label="Газ меньше">−</button></div>
    <div class="bottom-controls"><button id="brakeBtn" class="brake" type="button"><span class="brake-icon"></span><b>ТОРМОЗА</b></button><button id="gearBtn" class="gear" type="button"><span>GEAR</span><b>ШАССИ</b></button><button id="actionBtn" class="action" type="button"><span>ACT</span><b>ДЕЙСТВИЕ</b></button><button id="cameraBtn" class="camera" type="button"><span>◉</span><b>КАМЕРА</b></button></div>
    <div class="wallet hidden-wallet"><span>CR</span><b id="credits">0</b></div><button id="missionsBtn" class="ghost-hook" type="button">МИССИИ</button><button id="hangarBtn" class="ghost-hook" type="button">АНГАР</button><button id="freeBtn" class="ghost-hook" type="button">FREE</button><button id="uiMenuBtn" class="ghost-hook" type="button">МЕНЮ</button><div id="warning" class="warning"></div><div id="hint" class="hint"></div>
  </div>

  <div id="touch" class="touch hidden"><div class="stick-wrap"><div class="stick" id="touchStick"><i></i></div></div><button id="gyroQuickCalibrate" class="gyro-quick" type="button">GYRO<br><b>CAL</b></button><div class="yaw-control"><button data-touch="yawLeft">◀</button><span>RUDDER</span><button data-touch="yawRight">▶</button></div></div>

'''
html=html[:start]+flight+html[end:]

# Add start-screen / flight control bridge just before body closes. Existing V7 bindings for panels remain intact.
bridge=r'''<script>
(()=>{const key=(code,type='keydown')=>window.dispatchEvent(new KeyboardEvent(type,{code,bubbles:true}));
const bind=(id,code)=>{const e=document.getElementById(id);if(e)e.addEventListener('click',()=>key(code));};bind('cameraBtn','KeyC');bind('gearBtn','KeyG');bind('actionBtn','Space');bind('pauseBtn','KeyM');bind('uiMenuBtn','KeyM');
const start=document.getElementById('startDeck');document.getElementById('takeoffBtn').onclick=()=>start.classList.add('gone');document.getElementById('startHangar').onclick=()=>document.getElementById('hangarBtn').click();document.getElementById('startMissions').onclick=()=>document.getElementById('missionsBtn').click();document.getElementById('startSettings').onclick=()=>key('KeyM');
const br=document.getElementById('brakeBtn');for(const ev of ['pointerdown','touchstart'])br.addEventListener(ev,e=>{e.preventDefault();key('KeyB','keydown')},{passive:false});for(const ev of ['pointerup','pointercancel','touchend'])br.addEventListener(ev,e=>{e.preventDefault();key('KeyB','keyup')},{passive:false});
const sync=()=>{const c=document.getElementById('credits'),sc=document.getElementById('startCredits'),t=document.getElementById('throttle'),h=document.getElementById('throttleHandle');if(c&&sc)sc.textContent=c.textContent;if(t&&h)h.style.bottom=`calc(${Math.max(0,Math.min(100,+t.textContent||0))}% - 15px)`;requestAnimationFrame(sync)};sync();})();
</script>'''
html=html.replace('</body>',bridge+'\n</body>')

# Full reference-style skin. Dark beveled aviation controls, orange/green accents, large physical throttle and round instruments.
css=r''':root{font-family:Roboto,Arial,sans-serif;color:#fff;background:#111;--orange:#ff6b12;--green:#0ad17a}*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#0b0d0e;overscroll-behavior:none}button,input,select{font:inherit}.hidden{display:none!important}#game{position:fixed;inset:0;width:100%;height:100%;display:block}.boot{position:fixed;inset:0;z-index:100;background:linear-gradient(#171a1c,#090a0b);display:flex;flex-direction:column;justify-content:space-between;padding:28px 32px}.boot-mark{border-left:5px solid var(--orange);padding-left:12px}.logo{font-size:19px;font-weight:900;letter-spacing:.08em}.logo span{color:var(--orange)}.boot-title{font-size:9px;color:#a8adb0;margin-top:4px}.boot-bottom{width:min(520px,70vw)}.progress{height:8px;border:2px solid #555;background:#050505}.progress i{display:block;height:100%;width:3%;background:linear-gradient(90deg,#ef5b0b,#ff9d19)}.muted{margin-top:9px;font-size:10px;color:#b8bdc0}.start-deck{position:fixed;inset:0;z-index:25;pointer-events:none;transition:opacity .18s}.start-deck.gone{opacity:0;pointer-events:none}body:has(.start-deck:not(.gone)) .hud,body:has(.start-deck:not(.gone)) .touch{opacity:0!important;pointer-events:none!important}.top-status{pointer-events:auto;position:absolute;left:50%;top:max(0px,env(safe-area-inset-top));transform:translateX(-50%);height:42px;min-width:54%;display:flex;align-items:center;background:linear-gradient(#282b2d,#151719);border:2px solid #4a4d50;border-top:0;box-shadow:0 3px 8px #0009}.level-chip{height:100%;display:flex;align-items:center;gap:7px;padding:0 18px;border-right:1px solid #555}.level-chip span{font-size:20px;color:#d9a518}.level-chip b{font-size:9px;color:#e7d074}.level-chip small{font-size:7px;color:#777}.status-item{height:100%;min-width:74px;padding:0 14px;display:flex;align-items:center;justify-content:center;gap:10px;border-right:1px solid #555}.status-item span{font-size:23px;color:#f3c615}.status-item b{font-size:17px;color:#f3c615}.status-plus{height:30px;width:30px;margin:0 8px;border:0;background:#0aa769;color:#062b1d;font-size:24px;font-weight:900}.start-prompt{position:absolute;right:13%;bottom:24%;font-weight:900;font-size:24px;line-height:.82;color:#d3d3d3;text-shadow:0 2px 0 #222,1px 0 #222,-1px 0 #222}.start-prompt b{color:#ff7218}.start-prompt i{display:block;margin:8px auto 0;width:0;height:0;border-left:12px solid transparent;border-right:12px solid transparent;border-top:17px solid #fff}.start-nav{pointer-events:auto;position:absolute;left:3%;right:5%;bottom:max(0px,env(safe-area-inset-bottom));height:82px;display:flex}.start-nav button{position:relative;flex:1;border:0;border-top:4px solid #72777a;border-bottom:4px solid #252728;background:linear-gradient(#303335,#181a1b);box-shadow:inset 0 0 0 2px #111,0 -1px 0 #a6abad;color:#ff7118;font-size:14px;font-weight:700;text-transform:uppercase}.start-nav button:before,.start-nav button:after{content:"";position:absolute;top:4px;bottom:4px;width:3px;background:#6c7275}.start-nav button:before{left:0}.start-nav button:after{right:0}.start-nav .nav-icon{display:inline-block;margin-right:10px;font-size:22px}.start-nav .takeoff{flex:.82;background:linear-gradient(#243932,#12251f);border-color:#0bcf7a;color:#14d982;box-shadow:inset 0 0 0 2px #0a462f,0 -1px 0 #4af0a6}.start-nav .plane-glyph{font-size:28px;margin-left:12px}.hud{position:fixed;inset:0;z-index:15;pointer-events:none;text-shadow:0 2px 3px #000}.mission-callout{position:absolute;left:max(18px,env(safe-area-inset-left));top:max(12px,env(safe-area-inset-top));max-width:44vw;min-width:260px;padding:7px 13px 7px 10px;display:flex;gap:8px;background:linear-gradient(90deg,rgba(28,31,33,.93),rgba(28,31,33,.72));border:1px solid #5d6265;border-radius:13px;box-shadow:inset 0 1px 0 #8b9093,0 2px 3px #0008}.mission-callout b{display:block;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.mission-callout small{display:block;margin-top:2px;font-size:8px;color:#c0c4c6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.left-stack{position:absolute;left:max(18px,env(safe-area-inset-left));bottom:max(8px,env(safe-area-inset-bottom));display:flex;align-items:flex-end}.instrument-rail{position:absolute;left:0;bottom:108px;width:21px;height:152px;background:#191b1c;border:3px solid #5d6265;box-shadow:inset 0 0 0 2px #080808}.instrument-rail:before{content:"";position:absolute;left:5px;right:5px;top:6px;bottom:6px;background:#e8e8e8}.instrument-rail i{position:absolute;z-index:2;left:5px;right:5px;bottom:6px;height:32%;background:var(--orange)}.instrument-rail span{position:absolute;left:21px;bottom:-1px;padding:2px 4px;background:var(--orange);font-size:8px;font-weight:800;min-width:45px}.instrument-rail small{display:none}.round-instruments{display:flex;gap:6px}.round-gauge{position:relative;width:82px;height:82px;border-radius:50%;background:radial-gradient(circle,#151719 0 53%,#050606 54% 59%,#45494b 60% 66%,#111 67%);box-shadow:inset 0 0 0 2px #757b7e,0 2px 4px #0009}.round-gauge b{position:absolute;left:50%;top:45%;transform:translate(-50%,-50%);font-size:12px}.round-gauge small{position:absolute;left:50%;bottom:-14px;transform:translateX(-50%);padding:2px 6px;background:#242729;border:1px solid #62676a;font-size:7px;white-space:nowrap}.speed-gauge:before{content:"";position:absolute;inset:10px;border-radius:50%;border-top:4px solid #3ed321;border-right:4px solid #d7cf2c;border-bottom:4px solid #d53021;border-left:4px solid transparent;transform:rotate(-35deg)}.radar-gauge canvas{position:absolute;inset:8px;width:66px!important;height:66px!important;border-radius:50%}.right-stack{position:absolute;right:max(18px,env(safe-area-inset-right));top:max(12px,env(safe-area-inset-top));display:flex;flex-direction:column;gap:12px;pointer-events:auto}.square-action{width:34px;height:34px;padding:0;background:linear-gradient(#4a4d4f,#222425);border:2px solid #6b7073;box-shadow:inset 0 0 0 2px #151616;color:#eee;font-size:16px;font-weight:900}.square-action.time{font-size:10px}.throttle-unit{position:absolute;right:max(20px,env(safe-area-inset-right));bottom:max(8px,env(safe-area-inset-bottom));width:52px;height:238px;pointer-events:auto}.throttle-slot{position:absolute;left:14px;top:0;bottom:0;width:22px;background:#0b0c0d;border:4px solid #5b6063;box-shadow:inset 0 0 0 2px #000}.throttle-slot:before{content:"";position:absolute;left:5px;top:7px;bottom:7px;width:4px;background:#17191a}.throttle-slot i{position:absolute;z-index:3;left:-13px;bottom:-15px;width:40px;height:28px;border-radius:5px;background:linear-gradient(#44484a,#191b1c);border:3px solid #686d70;box-shadow:inset 0 0 0 2px #0d0e0e,0 2px 4px #000}.throttle-readout{position:absolute;right:52px;bottom:4px;background:#f0640f;padding:2px 5px;font-size:9px;font-weight:800;white-space:nowrap}.throttle-hit{position:absolute;left:0;width:52px;height:48%;opacity:0;border:0}.throttle-hit.up{top:0}.throttle-hit.down{bottom:0}.bottom-controls{position:absolute;left:120px;bottom:max(0px,env(safe-area-inset-bottom));height:52px;display:flex;gap:6px;pointer-events:auto}.bottom-controls button{min-width:75px;height:48px;padding:4px 8px;background:linear-gradient(#333638,#1b1d1e);border:2px solid #62676a;box-shadow:inset 0 0 0 2px #101112;color:#ddd}.bottom-controls button span{display:block;font-size:8px;color:#aaa}.bottom-controls button b{display:block;margin-top:2px;font-size:8px}.bottom-controls .brake{min-width:92px;display:flex;align-items:center;justify-content:center;gap:8px}.brake-icon{width:28px;height:14px;background:#8b9093;border:3px solid #333}.ghost-hook,.hidden-wallet{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;pointer-events:none!important;overflow:hidden!important}.warning{position:absolute;left:50%;top:16%;transform:translateX(-50%);padding:6px 13px;background:#9e261f;border:1px solid #ff7567;font-size:13px;font-weight:900}.warning:empty{display:none}.hint{display:none}.touch{position:fixed;inset:0;z-index:17;pointer-events:none}.stick-wrap{position:absolute;left:max(112px,env(safe-area-inset-left));bottom:66px;opacity:.15;pointer-events:auto}.stick{position:relative;width:88px;height:88px;border:2px solid #fff6;border-radius:50%;background:#0002}.stick i{position:absolute;left:50%;top:50%;width:34px;height:34px;border-radius:50%;background:#fff8;transform:translate(-50%,-50%)}.gyro-quick{position:absolute;left:210px;bottom:8px;width:52px;height:44px;pointer-events:auto;background:#26292a;border:2px solid #5d6265;color:#bbb;font-size:7px}.yaw-control{position:absolute;right:82px;bottom:8px;display:flex;align-items:center;gap:3px;pointer-events:auto}.yaw-control button{width:34px;height:36px;background:#282a2c;border:2px solid #5e6265;color:#ddd}.yaw-control span{font-size:7px}.panel{position:fixed;inset:0;z-index:40;background:rgba(6,7,8,.78);backdrop-filter:blur(5px);display:flex;align-items:center;justify-content:center;padding:18px}.panel-shell{width:min(680px,94vw);max-height:92vh;overflow:auto;background:linear-gradient(#303335,#17191a);border:3px solid #656a6d;box-shadow:inset 0 0 0 2px #101112,0 16px 50px #000c}.panel-shell.wide{width:min(1120px,94vw)}.panel .close{float:right;width:42px;height:40px;background:#2b2d2f;border:1px solid #555;color:#ddd;font-size:24px}.panel-kicker{padding:14px 16px 0;color:#ff7418;font-size:9px;font-weight:900}.panel-header{padding:5px 16px 12px}.panel-header h1{margin:0;font-size:28px}.panel-header p{margin:3px 0;color:#aaa;font-size:9px}.menu-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:6px;padding:0 14px 12px}.menu-grid button,.hangar-tools button{min-height:46px;background:#222526;border:2px solid #5f6467;color:#ff7418;font-size:10px;font-weight:800}.controls-card{margin:0 14px 14px;padding:12px;background:#1117;border:1px solid #5d6265}.gyro-settings{display:grid;grid-template-columns:auto auto 1fr;gap:8px;align-items:center}.gyro-settings button{height:34px;background:#292c2e;border:1px solid #676c6f;color:#ddd}.gyro-range{display:grid;grid-template-columns:auto 1fr auto;gap:5px;align-items:center;font-size:8px}.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:8px;padding:0 18px 20px}.card{padding:13px;background:linear-gradient(#282b2d,#191b1c);border:2px solid #4f5457}.card.selected,.card.complete{border-color:#0bcf7a}.card.locked{opacity:.48}.card .num{font-size:8px;color:#ff7418;font-weight:900}.card h3{margin:5px 0;font-size:16px}.card p{margin:0 0 9px;color:#aeb3b5;font-size:9px}.card button{width:100%;height:34px;background:#292c2e;border:1px solid #666;color:#ff7418;font-size:9px;font-weight:900}.hangar-tools{display:flex;gap:6px;padding:0 18px 12px}.hangar-tools input,.hangar-tools select{height:40px;padding:0 10px;background:#141617;border:1px solid #5d6265;color:#ddd}.hangar-tools input{flex:1}.toast{position:fixed;z-index:80;left:50%;bottom:92px;transform:translate(-50%,20px);opacity:0;padding:8px 14px;background:#17191a;border:1px solid #707477;color:#eee;font-size:10px;transition:.18s}.toast.show{opacity:1;transform:translate(-50%,0)}@media (orientation:landscape) and (max-height:620px){.top-status{height:34px}.start-nav{height:62px}.start-prompt{font-size:18px}.mission-callout{top:8px;left:10px;padding:5px 10px}.instrument-rail{height:125px;bottom:84px}.round-gauge{width:68px;height:68px}.radar-gauge canvas{width:52px!important;height:52px!important}.left-stack{left:10px}.throttle-unit{right:10px;height:185px}.right-stack{right:10px;top:8px;gap:7px}.square-action{width:28px;height:28px}.bottom-controls{left:95px;height:42px}.bottom-controls button{height:40px;min-width:62px}.bottom-controls .brake{min-width:78px}.stick-wrap{left:86px;bottom:50px}.stick{width:70px;height:70px}.yaw-control{right:65px}.gyro-quick{left:170px}}
'''

# Supplied reference keeps the aircraft much larger and camera lower/closer.
m=re.search(r"function updateCamera\(dt\)\{.*?\n\}",js,flags=re.S)
if m:
    camera=r'''function updateCamera(dt){
  if(!state.planeVisual)return;const q=state.planeVisual.quaternion,pos=state.planeVisual.position,p=state.planeAsset||AIRCRAFT[0];const len=Math.max(6,p.length||10),cf=p.cameraFactor||1;let local,lookLocal;
  if(state.cameraMode===0){const back=THREE.MathUtils.clamp(len*.95*cf,7.5,72),up=THREE.MathUtils.clamp(len*.27,2.3,16);local=new THREE.Vector3(0,up,back);lookLocal=new THREE.Vector3(0,Math.max(1.1,len*.055),-len*.95);}else if(state.cameraMode===1){local=new THREE.Vector3(0,Math.max(1.25,len*.085),Math.max(.55,len*.05));lookLocal=new THREE.Vector3(0,Math.max(1.1,len*.06),-len*1.25);}else{local=new THREE.Vector3(len*.58,Math.max(6,len*.22),Math.max(15,len*1.15));lookLocal=new THREE.Vector3(0,len*.06,-len*.9);}local.applyQuaternion(q);lookLocal.applyQuaternion(q);const desired=pos.clone().add(local),safeGround=terrainHeight(desired.x,desired.z)+2.2;if(desired.y<safeGround)desired.y=safeGround;camera.position.lerp(desired,1-Math.exp(-dt*(state.cameraMode===1?13:7.5)));camera.lookAt(pos.clone().add(lookLocal));
}'''
    js=js[:m.start()]+camera+js[m.end():]
js=js.replace('new THREE.PerspectiveCamera(66,','new THREE.PerspectiveCamera(58,')
if "k.has('KeyB')" not in js:js=js.replace("if(state.throttle<.2)state.speed*=Math.pow(.96,dt*60);","if(state.throttle<.2)state.speed*=Math.pow(.96,dt*60);if(k.has('KeyB'))state.speed*=Math.pow(.86,dt*60);")
# Vertical luminous checkpoint gates similar in function to the reference, without copying branded art.
rm=re.search(r"function createRing\(x,y,z,color\)\{.*?\n\}",js,flags=re.S)
if rm:
    ring=r'''function createRing(x,y,z,color){const g=new THREE.Group();g.position.set(x,y,z);const bm=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.22,depthWrite:false,blending:THREE.AdditiveBlending,side:THREE.DoubleSide});for(const dx of [-62,0,62]){const b=new THREE.Mesh(new THREE.BoxGeometry(24,620,24),bm.clone());b.position.set(dx,190,0);g.add(b);}const r=new THREE.Mesh(new THREE.TorusGeometry(112,9,12,48),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.82,depthWrite:false}));g.add(r);const glow=new THREE.PointLight(color,1.6,650,2);glow.position.y=45;g.add(glow);missionGroup.add(g);return g;}'''
    js=js[:rm.start()]+ring+js[rm.end():]
js=js.replace('renderer.toneMappingExposure=1.08;','renderer.toneMappingExposure=.84;').replace('new THREE.HemisphereLight(0xddefff,0x465035,1.25)','new THREE.HemisphereLight(0xddefff,0x465035,.92)').replace('new THREE.DirectionalLight(0xfff1d4,4.1)','new THREE.DirectionalLight(0xfff1d4,2.75)')
html_p.write_text(html);css_p.write_text(css);js_p.write_text(js)
assert 'rel="stylesheet" href="./style.css"' in html
assert 'throttle-unit' in css and 'start-nav' in css
assert 'spawnEmergencyPlaceholder' not in js
print('Applied V8 supplied-video reference UI')
